337: fn unsupported_field(
338:     definition: &CollaborationDefinitionRecord,
339:     field: &str,
340:     diagnostics: &mut Vec<FieldDiagnostic>,
341: ) {
342:     if let Some(requirement) = definition.document.get(field) {
343:         unsupported(
344:             requirement,
345:             field,
346:             "The field is preserved without an enforcing runtime component.".to_owned(),
347:             diagnostics,
348:         );
349:     }
350: }
