352: fn supported(
353:     effective: &mut Map<String, Value>,
354:     diagnostics: &mut Vec<FieldDiagnostic>,
355:     field: &str,
356:     value: Value,
357:     reason_code: &str,
358:     message: &str,
359: ) {
360:     effective.insert(field.to_owned(), value);
361:     diagnostics.push(FieldDiagnostic {
362:         pointer: format!("/{field}"),
363:         disposition: ConversionDisposition::Exact,
364:         reason_code: reason_code.to_owned(),
365:         message: message.to_owned(),
366:         effective_binding_ref: None, source_kind: None, source_definition: None,
367:     });
368: }
369: 
370: fn unsupported(
371:     requirement: &Value,
372:     field: &str,
373:     message: String,
374:     diagnostics: &mut Vec<FieldDiagnostic>,
375: ) {
376:     let required = requirement
377:         .get("required")
378:         .and_then(Value::as_bool)
379:         .unwrap_or(false);
380:     diagnostics.push(FieldDiagnostic {
381:         pointer: format!("/{field}"),
382:         disposition: if required {
383:             ConversionDisposition::RequiredUnsupported
384:         } else {
385:             ConversionDisposition::OptionalUnsupported
386:         },
387:         reason_code: "runtime.component-unavailable".to_owned(),
388:         message,
389:         effective_binding_ref: None, source_kind: None, source_definition: None,
390:     });
391: }
