393: fn string_field<'a>(value: &'a Value, field: &str) -> Result<&'a str, String> {
394:     value
395:         .get(field)
396:         .and_then(Value::as_str)
397:         .filter(|value| !value.is_empty())
398:         .ok_or_else(|| format!("Resolved model is missing '{field}'."))
399: }
