401: /// Legacy resource declarations remain required until a runtime mapping exists.
402: pub(super) fn resolve_legacy_team_context(definition: &CollaborationDefinitionRecord, binding: &Value, diagnostics: &mut Vec<FieldDiagnostic>) {
403:     let mut add = |pointer: String, code: &str| diagnostics.push(FieldDiagnostic {
404:         source_kind: Some(if pointer.starts_with("/contextGrants/") { crate::uar::domain::collaboration::CollaborationKind::DeploymentBinding } else { definition.kind.clone() }),
405:         source_definition: (!pointer.starts_with("/contextGrants/")).then(|| definition.identity.clone()),
406:         pointer, disposition: ConversionDisposition::RequiredUnsupported, reason_code: code.into(),
407:         message: "This declared resource has no executable mapping in the narrow team profile; explicitly revise the definition or binding.".into(), effective_binding_ref: None,
408:     });
409:     if definition.document.pointer("/context/mode").and_then(Value::as_str) == Some("authorized-fork") { add("/context/mode".into(), "TEAM_CONTEXT_REQUIRED_UNSUPPORTED"); }
410:     for field in ["artifacts", "memoryScopes"] {
411:         for (i, _) in definition.document.pointer(&format!("/context/{field}")).and_then(Value::as_array).into_iter().flatten().enumerate() { add(format!("/context/{field}/{i}"), "TEAM_CONTEXT_REQUIRED_UNSUPPORTED"); }
412:     }
413:     if matches!(definition.document.pointer("/context/history").and_then(Value::as_str), Some("selected" | "authorized-summary")) { add("/context/history".into(), "TEAM_CONTEXT_REQUIRED_UNSUPPORTED"); }
414:     for (i, _) in binding.get("contextGrants").and_then(Value::as_array).into_iter().flatten().enumerate() { add(format!("/contextGrants/{i}"), "TEAM_CONTEXT_REQUIRED_UNSUPPORTED"); }
415:     for (i, _) in definition.document.get("permittedChildren").and_then(Value::as_array).into_iter().flatten().enumerate() { add(format!("/permittedChildren/{i}"), "TEAM_CAPABILITY_UNSUPPORTED"); }
